	if (in_iter == eof)
		die({"Invalid input"});

	std::copy_if(ivec.cbegin(), ivec.cend(), out_iter_odd,
			[](const int &number) { return number % 2; });
	std::copy_if(ivec.cbegin(), ivec.cend(), out_iter_even,
			[](const int &number) { return !(number % 2); });
	return 0;
}

